function icon(name){return `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgIcons[name]||svgIcons.info}</svg>`;}
function fillIcons(root=document){els('[data-icon]',root).forEach(e=>{e.innerHTML=icon(e.dataset.icon)});}

const state={page:'overview',selected:13,overviewMode:'typology',atlasMode:'typology',atlasFilter:'all',atlasYear:2024,case:'toll',gateIndex:0,weights:{IDI:1/3,SEC:1/3,ESP:1/3},aggregation:'arithmetic',uploads:{},screening:{project:'',stage:'perencanaan',location:13,checks:{},notes:{}},aiBusy:false};
try{state.uploads=JSON.parse(localStorage.getItem('jnest_csv_v1')||'{}');state.screening={...state.screening,...JSON.parse(localStorage.getItem('jnest_gates_v1')||'{}')};}catch(e){/* privacy mode */}
function saveUploads(){try{localStorage.setItem('jnest_csv_v1',JSON.stringify(state.uploads));}catch(e){}}
function saveScreen(){try{localStorage.setItem('jnest_gates_v1',JSON.stringify(state.screening));}catch(e){}}
function region(id){return REGIONS.find(x=>x.id===Number(id))||REGIONS[12];}
function dataFor(r,year=2024){const base=PANEL_MODEL.row(r.id,year);const selected=state.uploads[`${year}:${r.name}`];if(selected)return {...r,...base,...selected,year,rank:null,source:'CSV tambahan pengguna · belum diaudit',imported:true};if(!base)return {...r,year,score:null,rank:null,IDI:null,SEC:null,ESP:null,source:'Data panel belum tersedia',imported:false};return {...r,...base,year,source:'Reproduksi panel olahan BPS–GEE yang diunggah · asal primer belum diaudit',imported:false};}
function zoneText(r){return r.zone==='rebana'?'Rebana resmi':r.zone==='pantura'?'Pembanding Pantura':'Jawa Barat';}
function tint(hex,alpha=0.14){let h=hex.replace('#','');if(h.length!==6)return `rgba(41,118,117,${alpha})`;const v=parseInt(h,16);return `rgba(${v>>16},${(v>>8)&255},${v&255},${alpha})`;}
function colorNum(value){if(!Number.isFinite(value))return '#dce7e6';const t=Math.max(0,Math.min(1,value/100));const from=[225,239,234],to=[14,92,100];const v=from.map((f,i)=>Math.round(f*(1-t)+to[i]*t));return `rgb(${v.join(',')})`;}
function rowColor(r,mode,year){if(mode==='typology')return STUDY.types[r.typology]?.color||'#dce7e6';const d=dataFor(r,year);return colorNum(d[mode==='score'?'score':mode]);}
function typePill(code){const t=STUDY.types[code];return `<span class="type-pill" style="background:${tint(t.color,.15)};color:${t.color}">${code}</span>`;}
function getSelectedProfileText(r){const t=STUDY.types[r.typology];return `${r.name} termasuk tipologi ${t.name}. ${t.desc} Skor kabupaten/kota hanya memberi konteks penapisan; evaluasi lokasi dan investasi memerlukan bukti tapak.`;}
function fillSelect(id,items,selected){const e=$(id);if(!e)return;e.innerHTML=items.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');e.value=String(selected);}
function toast(msg){const e=$('toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),3600);}
function gotoPage(page){if(!$('page-'+page))return;state.page=page;els('.page').forEach(e=>e.classList.toggle('active',e.id==='page-'+page));els('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page===page&&(page!=='policy'||Number(e.dataset.flowStep||0)===(window.JNestPolicy?.getStep?.()||0))&&(page!=='lab'||!e.dataset.flowStep)));const labels={calculate:'Hitung indeks J-NEST',policy:'Simulasi penggunaan J-NEST',lab:'Laboratorium kebijakan',evaluation:'Evaluasi nilai tambah',governance:'Alur DPMPTSP–Bappeda',clearance:'Jejak perizinan resmi',overview:'Ringkasan penelitian',atlas:'Eksplorasi wilayah',typology:'Tipologi wilayah',sensitivity:'Uji sensitivitas',screening:'Penapisan G0–G4',cases:'Studi kasus Patimban',skk:'Orientasi SKK',ai:'Tanya penelitian',method:'Metode & data'};$('breadcrumb').textContent=labels[page];history.replaceState(null,'',`#${page}`);$('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'instant'});if(page==='atlas')renderAtlas();if(page==='overview')renderOverview();if(page==='screening')renderScreen();}
function selectRegion(id,goToAtlas=false){state.selected=Number(id);$('atlas-region').value=String(id);renderOverview();renderAtlas();if(goToAtlas)gotoPage('atlas');}

function createMap(rootId,mode,year,filter,selectedId){const host=$(rootId);if(!host)return;const zones=filter==='all'?null:filter;
  const polygons=MAP_GEOMETRY.polygons.map(f=>{const r=region(f.id),d=dataFor(r,year);const shown= !zones||r.zone===zones;const selected=f.id===selectedId;return `<path class="map-polygon ${selected?'is-selected':''}" data-region="${f.id}" d="${f.p}" fill="${rowColor(r,mode,year)}" opacity="${shown?1:.19}"><title>${esc(r.name)} · ${mode==='typology'?STUDY.types[r.typology].name:Number.isFinite(d[mode==='score'?'score':mode])?fmt(d[mode==='score'?'score':mode],1):'Angka belum tersedia'}</title></path>`;}).join('');
  const markers=REGIONS.map(r=>{const p=MAP_GEOMETRY.markers[r.id];const selected=r.id===selectedId;const shown=!zones||r.zone===zones;const label=String(r.id).padStart(2,'0');return `<g class="map-region-marker ${selected?'active':''} ${r.zone==='rebana'?'focus':''}" data-region="${r.id}" role="button" tabindex="0" aria-label="Pilih ${esc(r.name)}" opacity="${shown?1:.45}"><title>${esc(r.name)}${Number.isFinite(dataFor(r,year).score)?' · '+fmt(dataFor(r,year).score):''}</title><circle cx="${p.x}" cy="${p.y}" r="28"/><text x="${p.x}" y="${p.y+2}">${label}</text><circle class="map-hit" cx="${p.x}" cy="${p.y}" r="55" fill="transparent" stroke="none"/></g>`;}).join('');
  host.innerHTML=`<svg viewBox="0 0 2570 2070" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Peta skematik hasil penelusuran Gambar 2, berisi 27 kabupaten dan kota Jawa Barat">${polygons}${markers}</svg>`;
  els('[data-region]',host).forEach(e=>{const choose=()=>selectRegion(e.dataset.region);e.addEventListener('click',choose);e.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();choose();}});});
}
function mapLegend(target,mode,year){if(!$(target))return;if(mode==='typology'){$(target).innerHTML=TYPE_ORDER.map(code=>`<div class="legend-item"><span class="legend-dot" style="background:${STUDY.types[code].color}"></span>${code}</div>`).join('')+'<div class="legend-item"><span style="color:#cb944d;font-size:15px">◌</span>Penanda 7 Rebana</div>';return;}
  $(target).innerHTML=`<div class="legend-item"><span class="legend-gradient"></span> Rendah → Tinggi (0–100)</div><div class="legend-item"><span class="legend-dot" style="background:#dce7e6;border:1px solid #b5cac8"></span> Data tidak tersedia</div>${'<div class="legend-item">Skor dihitung dari panel 2020–2024</div>'}`;}
function detailHTML(r,year=2024,compact=false){const d=dataFor(r,year),type=STUDY.types[r.typology],known=Number.isFinite(d.score);const rank=Number.isFinite(d.rank)?`${d.rank} / 27`:'—';const dims=['IDI','SEC','ESP'];
  const dimHtml=dims.every(k=>Number.isFinite(d[k]))?dims.map(k=>`<div class="dim-row"><span class="dim-label">${k}</span><div class="bar-track"><div class="bar-fill" style="width:${d[k]}%"></div></div><span class="dim-val">${fmt(d[k])}</span></div>`).join(''):`<div class="dim-missing">Belum ada skor IDI, SEC, dan ESP lengkap untuk ${esc(r.name)} tahun ${year} dalam data saat ini. Tipologi referensi tahun 2024 tetap tersedia.</div>`;
  return `<div class="region-profile"><div class="region-score"><strong>${known?fmt(d.score):'—'}</strong><div><span>J-NEST · ${year}</span>${known?'Skala 0–100':'Skor belum tersedia'}</div></div><div class="region-meta"><span class="meta-pill">${zoneText(r)}</span>${typePill(r.typology)}<span class="meta-pill">Peringkat: ${rank}</span></div><div class="profile-divider"></div><div class="mini-section-head"><span>Tiga dimensi</span><small>Skor 0–100</small></div>${dimHtml}<div class="region-insight"><b>${esc(type.name)} · tipologi 2024</b><p>${esc(type.desc)}</p></div><div class="region-source"><span>${esc(d.source)}</span>${d.imported?'<b>DATA IMPOR</b>':''}</div>${compact?`<button class="button button-soft detail-open" data-goto="atlas">Eksplorasi lebih lanjut ${icon('arrow-right')}</button>`:''}</div>`;
}
function renderOverview(){const current=region(state.selected);const mode=state.overviewMode;createMap('overview-map',mode,2024,'all',current.id);mapLegend('overview-map-legend',mode,2024);$('overview-region-name').textContent=current.name;$('overview-region-tag').textContent=zoneText(current);$('overview-region-detail').innerHTML=detailHTML(current,2024,true);els('#overview-map-mode button').forEach(e=>e.classList.toggle('active',e.dataset.mode===mode));}
function renderRanking(){const host=$('overview-ranking');const top=PANEL_MODEL.byYear[2024].slice(0,15);
  host.innerHTML=`<div class="rank-list">${top.map((d,i)=>{const r=region(d.regionId);return `<div class="rank-row" data-select-region="${r.id}" role="button" tabindex="0"><span class="rank-no">${String(i+1).padStart(2,'0')}</span><span class="rank-name">${esc(r.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${d.score}%"></div></div><span class="rank-score">${fmt(d.score)}</span></div>`;}).join('')}</div>`;
}
function atlasFiltered(){return REGIONS.filter(r=>state.atlasFilter==='all'||r.zone===state.atlasFilter);}
function renderAtlas(){const year=state.atlasYear,mode=state.atlasMode,current=region(state.selected);$('atlas-region').value=String(current.id);$('atlas-filter').value=state.atlasFilter;$('atlas-mode').value=mode;$('atlas-year').value=String(year);
  $('atlas-map-title').textContent=(mode==='typology'?'Peta tipologi · referensi 2024':mode==='score'?'Peta skor J-NEST':`Peta skor ${mode}`)+(mode==='typology'?'':` · ${year} · hasil hitung ulang`);
  createMap('atlas-map',mode,year,state.atlasFilter,current.id);mapLegend('atlas-map-legend',mode,year);$('atlas-detail-title').textContent=current.name;$('atlas-region-detail').innerHTML=detailHTML(current,year);
  renderCompare();renderRebanaTable();
}
function renderCompare(){const left=region($('compare-left').value||13),right=region($('compare-right').value||11),d1=dataFor(left,state.atlasYear),d2=dataFor(right,state.atlasYear);const keys=['IDI','SEC','ESP'];const valid=keys.every(k=>Number.isFinite(d1[k])&&Number.isFinite(d2[k]));
  if(!valid){$('compare-chart').innerHTML=`<div class="compare-missing">Profil dimensi lengkap belum tersedia untuk kedua wilayah pada tahun ${state.atlasYear}.<br>Periksa data impor pengguna bila profil tidak lengkap. Profil hitung ulang tersedia pada 27 wilayah, 2020–2024.</div>`;return;}
  $('compare-chart').innerHTML=keys.map(k=>`<div class="compare-dim"><div><div class="bar-track left-track"><div class="bar-fill" style="width:${d1[k]}%"></div></div><div class="compare-val"><span>${fmt(d1[k])}</span><span>${esc(left.name)}</span></div></div><div class="dim-title">${k}</div><div><div class="bar-track"><div class="bar-fill" style="width:${d2[k]}%;background:#d2b471"></div></div><div class="compare-val"><span>${esc(right.name)}</span><span>${fmt(d2[k])}</span></div></div></div>`).join('')+`<div class="region-insight" style="margin:15px 0 2px">Perbandingan ini bersifat deskriptif. Skor dimensi tidak menunjukkan kelayakan hukum, cadangan air, atau besaran dampak proyek.</div>`;}
function renderRebanaTable(){const ids=[16,11,15,10,13,8,9,12,22],year=state.atlasYear;const body=el('#rebana-table tbody');body.innerHTML=ids.map(id=>{const r=region(id),d=dataFor(r,year);return `<tr data-select-region="${id}" style="cursor:pointer"><td><b>${esc(r.name)}</b>${r.zone==='pantura'?' †':''}</td><td><span class="zone-tag ${r.zone==='pantura'?'compare':''}">${zoneText(r)}</span></td><td class="num">${fmt(d.score)}</td><td class="num">${fmt(d.IDI)}</td><td class="num">${fmt(d.SEC)}</td><td class="num">${fmt(d.ESP)}</td><td>${d.rank||'—'}/27</td><td>${typePill(r.typology)}</td></tr>`;}).join('');
}
function renderTypes(){const host=$('type-grid');host.innerHTML=TYPE_ORDER.map(code=>{const t=STUDY.types[code],members=REGIONS.filter(r=>r.typology===code);return `<div class="panel type-card"><div class="type-topline" style="background:${t.color}"></div><span class="type-count">${t.n.toString().padStart(2,'0')}</span><span class="type-code" style="color:${t.color}">${code}</span><h3>${esc(t.name)}</h3><p>${esc(t.short)}. ${esc(t.desc)}</p><div class="type-card-members"><b>Anggota:</b> ${members.map(r=>`<button data-select-region="${r.id}" title="Lihat ${esc(r.name)}">${esc(r.name)}</button>`).join(' · ')}</div></div>`;}).join('');
  $('typology-heatmap').innerHTML=`<div class="heatmap"><div class="heatmap-header"><span>Tipologi</span><span>Industri (IDI)</span><span>Sosial (SEC)</span><span>Vegetasi (ESP)</span></div>${TYPE_ORDER.map(code=>{const t=STUDY.types[code];return `<div class="heatmap-row"><span class="heatmap-type"><i class="legend-dot" style="background:${t.color}"></i>${code} · n=${t.n}</span>${['IDI','SEC','ESP'].map(k=>`<span class="heatmap-cell" style="background:${colorNum(t[k])};color:${t[k]>60?'#fff':'#225b5f'}">${fmt(t[k])}</span>`).join('')}</div>`;}).join('')}</div>`;}
function renderSensitivity(){const host=$('sensitivity-rows');host.innerHTML=STUDY.sensitivity.map(s=>`<tr><td><b>${esc(s.name)}</b><div class="table-help">${esc(s.note)}</div></td><td class="num">${fmt(s.spearman,3)}</td><td class="num">${fmt(s.meanShift,2)}</td><td class="num">${s.maxShift}</td><td class="num">${s.ari===null?'—':fmt(s.ari,3)}</td></tr>`).join('');renderWeightControls();renderSimulation();}
function setWeight(k,value){const changed=Math.max(0,Math.min(100,Number(value)))/100;const other=['IDI','SEC','ESP'].filter(x=>x!==k);const previous=state.weights[other[0]]+state.weights[other[1]];state.weights[k]=changed;
  if(previous>0){state.weights[other[0]]=(1-changed)*state.weights[other[0]]/previous;state.weights[other[1]]=(1-changed)*state.weights[other[1]]/previous;}
  else{state.weights[other[0]]=(1-changed)/2;state.weights[other[1]]=(1-changed)/2;}
  renderWeightControls();renderSimulation();}
function renderWeightControls(){const names={IDI:'Aktivitas industri · IDI',SEC:'Profil sosial-ekonomi · SEC',ESP:'Vegetasi–termal · ESP'};
  $('weight-controls').innerHTML=['IDI','SEC','ESP'].map(k=>`<div class="weight-row"><div class="weight-row-head"><span>${names[k]}</span><b>${fmt(state.weights[k]*100,1)}%</b></div><input type="range" min="0" max="100" value="${(state.weights[k]*100).toFixed(1)}" step="1" data-weight="${k}" aria-label="Bobot ${k}"></div>`).join('');const total=Object.values(state.weights).reduce((a,b)=>a+b,0)*100;$('weight-total').textContent=`Total bobot: ${fmt(total,1)}% · Otomatis dinormalisasi ke 100%`;
}
function scoreSimulation(r,weights=state.weights,agg=state.aggregation){const d=dataFor(r,2024);if(!['IDI','SEC','ESP'].every(k=>Number.isFinite(d[k])))return null;return agg==='geometric'?Math.exp(['IDI','SEC','ESP'].reduce((a,k)=>a+weights[k]*Math.log(Math.max(1e-6,d[k])),0)):['IDI','SEC','ESP'].reduce((a,k)=>a+weights[k]*d[k],0);}
function renderSimulation(){const year=2024;const choices=PANEL_MODEL.whatIf(year,state.weights,state.aggregation);const shifts=choices.map(x=>Math.abs(x.shift));const mean=shifts.reduce((a,b)=>a+b,0)/shifts.length,max=Math.max(...shifts);
 $('simulation-results').innerHTML=`<div class="sim-meta"><b>27 wilayah · basis provinsi</b><span>Pergeseran rerata: ${fmt(mean,2)} · maksimum ${max} posisi</span></div><div class="simulation-list">${choices.map((row,i)=>{const diff=row.shift;return `<div class="simulation-row" title="Posisi ${row.rank}/27 · baseline ${row.baseRank}/27 · data panel 2024"><span class="rank-no">${row.rank}</span><span class="rank-name">${esc(row.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,row.score))}%;background:${diff===0?'#4d9d98':diff>0?'#42a88e':'#bba468'}"></div></div><span class="rank-score">${fmt(row.score)}</span><small class="sim-rank-shift" title="Perubahan peringkat terhadap baseline hitung ulang">${diff===0?'—':diff>0?'↑'+diff:'↓'+(-diff)}</small></div>`;}).join('')}</div><div class="panel-footer">Simulasi menggunakan skor IDI–SEC–ESP 2024 dari panel 135 baris, 27 wilayah. Perubahan bobot dan agregasi bersifat eksploratif, bukan ranking kelayakan proyek. Panah menunjukkan perpindahan peringkat dari agregasi aritmetika setara.</div>`;
}
function screenCount(){return Object.values(state.screening.checks||{}).filter(v=>v!=='pending'&&v).length;}
function renderScreen(){const s=state.screening;$('screen-project').value=s.project||'';$('screen-stage').value=s.stage||'perencanaan';$('screen-location').value=String(s.location||13);renderScreenContext();renderGateNav();renderGateDetail();updateProgress();}
function renderScreenContext(){const r=region(state.screening.location),d=dataFor(r,2024);$('screen-location-context').innerHTML=`<b>${esc(r.name)}</b> · ${typePill(r.typology)}<br>Skor 2024: <b>${fmt(d.score)}</b> · ${zoneText(r)}<br><span>Profil wilayah adalah konteks; status proyek harus didukung bukti tapak.</span>`;}
function updateProgress(){const n=screenCount();$('screen-progress-text').textContent=`${n} / 15`;$('screen-progress-bar').style.width=(100*n/15)+'%';}
function renderGateNav(){$('gate-nav').innerHTML=STUDY.gates.map((g,i)=>{const completed=g.checklist.every((_,j)=>{const v=state.screening.checks[`${g.id}:${j}`];return !!v&&v!=='pending';});return `<button class="gate-nav-btn ${i===state.gateIndex?'active':''}" data-gate="${i}"><span class="gate-step">${g.id}</span><span><b>${esc(g.name)}</b><small>${esc(g.subtitle)}</small></span>${completed?'<span class="gate-check">✓</span>':''}</button>`;}).join('');}
function renderGateDetail(){const g=STUDY.gates[state.gateIndex];$('gate-detail').innerHTML=`<div class="gate-head"><div><span class="gate-step-large">${g.id} · TAHAP ${state.gateIndex+1} DARI 5</span><h2>${esc(g.name)}</h2><p>${esc(g.subtitle)} · ${esc(g.source)}</p></div></div><h3 class="gate-question">“${esc(g.question)}”</h3><div class="panel-eyebrow">CHECKLIST KETERSEDIAAN &amp; PENELUSURAN BUKTI</div>${g.checklist.map((item,i)=>{const v=state.screening.checks[`${g.id}:${i}`]||'pending';return `<div class="gate-item"><div class="gate-item-title">${i+1}. ${esc(item)}</div><select data-check="${g.id}:${i}" aria-label="Status bukti: ${esc(item)}"><option value="pending" ${v==='pending'?'selected':''}>Belum ditelaah</option><option value="available" ${v==='available'?'selected':''}>Dinyatakan tersedia</option><option value="needs" ${v==='needs'?'selected':''}>Perlu dilengkapi</option><option value="irrelevant" ${v==='irrelevant'?'selected':''}>Tidak relevan*</option></select></div>`;}).join('')}<div class="field gate-notes"><label for="gate-notes">Catatan bukti, dokumen, alasan, dan penanggung jawab</label><textarea id="gate-notes" rows="4" placeholder="Tulis sumber dokumen, lokasi/bagian, asumsi, atau kebutuhan bukti..."></textarea></div><div class="gate-followup"><b>Usulan tindak lanjut</b>${esc(g.follow)}<br><small>*Status tidak relevan perlu memiliki alasan yang dapat ditelusuri.</small></div>`;
  $('gate-notes').value=state.screening.notes[g.id]||'';$('prev-gate').disabled=state.gateIndex===0;$('next-gate').innerHTML=state.gateIndex===4?'Tinjau catatan '+icon('check-circle'):'Tahap berikutnya '+icon('arrow-right');}
function screenNext(){if(state.gateIndex<4){state.gateIndex++;renderGateNav();renderGateDetail();}else{const n=screenCount();toast(`${n} dari 15 status terisi. Ekspor JSON untuk menyimpan catatan penelaahan.`);}}
function exportScreen(){const s=state.screening;const checks=STUDY.gates.map(g=>({tahap:g.id,nama:g.name,pertanyaan:g.question,pemeriksaan:g.checklist.map((label,i)=>({label,status:s.checks[`${g.id}:${i}`]||'pending'})),catatan:s.notes[g.id]||'',tindak_lanjut_usulan:g.follow}));
  downloadJSON({tipe:'CATATAN-PENAPISAN-J-NEST-SKK',disclaimer:'Isian pengguna, bukan audit resmi, persetujuan, atau nilai kompensasi ekologis.',tanggal_ekspor:new Date().toISOString(),proyek:s.project||'Belum diisi',tahap_proyek:s.stage,wilayah:region(s.location).name,profil_wilayah_tahun:2024,langkah:checks},'jnest-catatan-penapisan.json');toast('Catatan penapisan diekspor sebagai JSON.');}
function renderCase(){els('.case-tabs button').forEach(e=>e.classList.toggle('active',e.dataset.case===state.case));const target=$('case-content');
  if(state.case==='toll'){const evidence=[
    ['G0','Tersedia sebagian','Laporan bantuan teknis, RKL–RPL dan laporan pemantauan telah ditelaah, tetapi belum menyusun rangkaian sepadan dampak residual.'],
    ['G1','Persetujuan disebut','Laporan pemantauan menyebut persetujuan AMDAL 17 Mei 2022; penelitian tidak mengaudit keabsahan semua izin.'],
    ['G2','Alternatif dibandingkan','Laporan JICA 2022 merangkum tiga pilihan trase yang dibandingkan dalam kajian tahun 2017.'],
    ['G3','Peran tercatat','RKL–RPL memuat metode, lokasi dan instansi pemantauan; pelaksanaan tanggapan individual belum diaudit.'],
    ['G4','Belum dapat diatribusikan','BOD baseline 6–13,6 mg/L pada tujuh titik melebihi standar 3 mg/L dalam dokumen, tetapi tidak membuktikan dampak konstruksi.']
  ];target.innerHTML=`<div class="case-stats"><div class="panel case-stat"><span>LOKASI</span><b>Kab. Subang</b><small>J-NEST 2024: 46,22 (diuraikan dalam paper)</small></div><div class="panel case-stat"><span>BAKU MUTU BOD DI LAPORAN</span><b>3 mg/L</b><small>RKL–RPL 2022; perbandingan studi</small></div><div class="panel case-stat"><span>BOD TITIK YANG DILABELI BASELINE</span><b>6–13,6</b><small>mg/L · 7 titik · Laporan Pemantauan I</small></div></div><div class="case-grid"><div class="panel"><div class="panel-eyebrow">TABEL 9 · KETERLACAKAN</div><h3>Hasil pemeriksaan G0–G4 pada korpus dokumen</h3>${evidence.map(row=>`<div class="case-evidence-row"><span class="evidence-code">${row[0]}</span><div class="evidence-text"><b>${row[1]}</b><small>${row[2]}</small></div></div>`).join('')}</div><div class="panel"><div class="panel-eyebrow">BATAS ATRIBUSI</div><h3>Pelampauan standar ≠ dampak konstruksi.</h3><p>Dokumen yang ditinjau sudah memuat perbandingan alternatif, rencana pemantauan, dan hasil BOD. Akan tetapi, untuk menghubungkan perubahan air dengan jalan tol diperlukan pengamatan sepadan pada titik, parameter, metode, dan waktu, serta mempertimbangkan sumber pencemar lainnya.</p><div class="case-warning"><b>Kesimpulan dokumen</b>Dampak residual dan besaran kompensasi ekologis Tol Akses Patimban belum dapat ditentukan dari korpus penelitian ini.</div><p><b>Kelanjutan yang dapat diuji:</b> susun seri pengamatan sepadan dan penilaian atribusi sesuai mekanisme resmi, tanpa menyamakan label baseline dengan bukti dampak.</p><p><a href="https://openjicareport.jica.go.jp/pdf/12371431.pdf" target="_blank" rel="noopener noreferrer">Lihat laporan JICA 2022 ↗</a></p></div></div>`;
  } else {target.innerHTML=`<div class="case-stats"><div class="panel case-stat"><span>NILAI INVESTASI · DUA PROFIL</span><b>Rp134,2 M</b><small>Angka investasi yang konsisten pada dua sumber</small></div><div class="panel case-stat"><span>INTERNAL RATE OF RETURN</span><b>10,9%</b><small>Sama pada lembar dan portal</small></div><div class="panel case-stat"><span>WAKTU PENGEMBALIAN</span><b>11 tahun</b><small>Skema Build Operate Transfer</small></div></div><div class="case-grid"><div class="panel"><div class="panel-eyebrow">TABEL 10 · KONSISTENSI PENAWARAN</div><h3>Perbandingan dua dokumen publik</h3><div class="table-scroll"><table class="case-table"><thead><tr><th>Bidang</th><th>Lembar promosi</th><th>Portal Investasi Jabar</th></tr></thead><tbody><tr><td>Investasi</td><td>Rp134,2 miliar</td><td>Rp134.200.000.000</td></tr><tr><td>IRR</td><td>10,9%</td><td>10,9%</td></tr><tr><td><b>NPV</b></td><td>“IDR 29.0 Milion”</td><td>“29,000,000,000”*</td></tr><tr><td>Payback</td><td>11 tahun</td><td>11 tahun</td></tr><tr><td>Skema</td><td>Build Operate Transfer</td><td>Build Operate Transfer</td></tr></tbody></table></div><p>*Mata uang tidak dicantumkan pada bidang NPV portal. Ejaan dan format angka dipertahankan sesuai sumber.</p></div><div class="panel"><div class="panel-eyebrow">BUTUH KLARIFIKASI</div><h3>NPV dan kecukupan pasokan belum dapat divalidasi.</h3><div class="case-warning"><b>Perbedaan penyajian NPV</b>Apabila kedua penulisan ditafsirkan sebagai rupiah, pembacaan nominal bisa berbeda 1.000 kali. Penelitian tidak memutuskan angka yang benar tanpa konfirmasi dan model arus kas.</div><p>Kapasitas terpasang tidak identik dengan produksi aktual atau tambahan pasokan yang dapat dialokasikan setelah pengguna eksisting diperhitungkan. Pemeriksaan memerlukan neraca layanan dan skenario yang konsisten.</p><p><b>Alternatif untuk ditelaah:</b> penyesuaian kapasitas atau pentahapan layanan bila layak menurut kajian operator, bukan kesimpulan bahwa kapasitas air pasti tersedia.</p><p><a href="https://dpmptsp.jabarprov.go.id/investasi-jabar/src/assets/invest/file/Clean_Water_Services_for-the_Patimban_Port_Area%26Surroundings.pdf" target="_blank" rel="noopener noreferrer">Lihat profil publik Patimban ↗</a></p></div></div>`;}
}
function renderSKK(){const cards=[
    ['I','Pemeliharaan sumber penghidupan','Fungsi lingkungan dipahami bersama pengguna dan penghidupannya. Pertanyaan terapan: fungsi serta pengguna sumber daya apa yang relevan bagi alternatif proyek?','SKK Bagian I','SKK tidak menyediakan ambang ekologis atau neraca air.'],
    ['XV–XVI','Ketepatan sumber pengetahuan','Sumber pengetahuan harus sesuai dengan persoalannya. Pertanyaan terapan: apakah kompetensi penelaah sesuai dengan klaim sumber daya yang diperiksa?','SKK Bagian XV–XVI','Bukan sertifikasi profesi atau pembagian kewenangan modern.'],
    ['TRITANGTU','Pembedaan peran dan tanggung jawab','Pisahkan pihak yang menyusun klaim, memeriksa bukti, memutuskan, dan menindaklanjuti isu material.','Bagian tritangtu dalam SKK','Rama–resi–prabu tidak dipadankan langsung dengan lembaga pemerintah sekarang.']
  ];$('skk-cards').innerHTML=cards.map(([num,title,body,source,caution])=>`<div class="panel skk-card"><span class="skk-no">${num}</span><h3>${title}</h3><p>${body}</p><p><b>Batas:</b> ${caution}</p><div class="skk-source">${source}</div></div>`).join('');}
function renderMethod(){const names={IDI:'Aktivitas industri (IDI)',SEC:'Profil sosial-ekonomi (SEC)',ESP:'Vegetasi–termal (ESP)'};
  $('method-weights').innerHTML=`<div class="method-table">${['IDI','SEC','ESP'].map(k=>`<div class="method-dim"><div class="method-dim-head"><span>${names[k]}</span><span>Jumlah bobot: 1,000000</span></div>${STUDY.dimensions[k].weights.map(([name,weight,sign],i)=>{const key=PANEL_MODEL.DIMENSIONS[k][i];return `<div class="method-indicator"><span>${esc(name)}</span><span>Arah ${sign}</span><span>${fmt(PANEL_MODEL.weights[k][key],6)}</span></div>`;}).join('')}</div>`).join('')}</div>`;
  $('method-references').innerHTML=`<div class="references">${STUDY.references.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${icon('external-link')} ${esc(r.label)}</a>`).join('')}</div>`;}

// Local, strictly bounded reference answers; these are not generative AI responses.
function localAnswer(query){const q=query.toLocaleLowerCase('id-ID').trim();const explicit=REGIONS.filter(r=>q.includes(r.name.toLocaleLowerCase('id-ID')));const mentions=explicit.length?explicit:REGIONS.filter(r=>q.includes(r.name.replace(/^Kab\. |^Kota /,'').toLocaleLowerCase('id-ID')));
  // For observations that are now present in the processed panel, always use deterministic local values.
  const yrs=PANEL_MODEL.years.filter(year=>q.includes(String(year)));
  if(mentions.length&&yrs.length&&/(skor|nilai|idi|sec|esp|indeks|peringkat|profil|berapa|perbandingan|data)/.test(q)){
    const regionMatches=[...mentions].sort((a,b)=>b.name.length-a.name.length);
    if(regionMatches.length>1&&!/(kabupaten|kab\.|kota)/.test(q))return 'Nama wilayah belum spesifik. Pilih Kabupaten atau Kota pada halaman Panel & Audit Data untuk melihat nilainya berdasarkan kunci wilayah–tahun.';
    const r=regionMatches[0],items=yrs.map(year=>{const d=PANEL_MODEL.row(r.id,year);return `${year}: J-NEST ${fmt(d.score,3)}, IDI ${fmt(d.IDI,3)}, SEC ${fmt(d.SEC,3)}, ESP ${fmt(d.ESP,3)}, peringkat ${d.rank}/27`;});
    const note=yrs.length===2?`\nSelisih skor ${yrs[1]} dibanding ${yrs[0]}: ${fmt(PANEL_MODEL.row(r.id,yrs[1]).score-PANEL_MODEL.row(r.id,yrs[0]).score,3)} poin.`:'';
    return `${r.name}, hasil perhitungan ulang dari panel olahan:\n${items.join('\n')}${note}\n\nSumber: tiga CSV terunggah; normalisasi min–maks global dan CRITIC sesuai paper. Belum ada audit independen asal data primer. Skor bukan keputusan investasi atau bukti dampak proyek.`;
  }
  if(q.includes('idi')&&(q.includes('sec')||q.includes('esp')))return 'J-NEST menyajikan tiga dimensi yang berbeda: IDI (aktivitas industri) memakai ln PDRB industri, NDBI, dan cahaya malam; SEC (profil sosial-ekonomi terpilih) memakai ln jumlah penduduk, persentase kemiskinan, dan tingkat pengangguran terbuka; ESP (vegetasi–termal) memakai NDVI serta suhu permukaan lahan. Delapan indikator dinormalisasi sebelum dibobot dengan CRITIC di dalam setiap dimensi. Skor utama J-NEST adalah rata-rata ketiga dimensi dengan bobot sama (⅓ per dimensi). SEC bukan indeks kesejahteraan per kapita dan ESP bukan ukuran seluruh kondisi ekologis.\n\nSumber: Tabel 1 dan Metodologi, hlm. 4–6.';
  if(q.includes('apa itu j-nest')||q.includes('apa itu jnest')||q.includes('tentang penelitian')||q.includes('tujuan penelitian'))return 'J-NEST adalah kerangka penapisan awal investasi yang memadukan diagnosis profil 27 kabupaten/kota Jawa Barat melalui IDI, SEC, dan ESP dengan pertanyaan berbasis Siksa Kandang Karesian serta pemeriksaan bukti proyek G0–G4. Penelitian memakai panel 2020–2024, studi kasus Tol Akses Patimban, dan dua materi penawaran proyek air bersih Patimban. Indeks wilayah bukan persetujuan proyek, dan nilai tambah kerangka dibanding prosedur pemerintah yang sudah berjalan belum diuji.\n\nSumber: Abstrak, Pendahuluan, dan Kesimpulan.';
  if((q.includes('tahun')||q.includes('2020')||q.includes('2021')||q.includes('2022')||q.includes('2023'))&&!q.includes('2024')&&!q.includes('patimban'))return 'Panel olahan yang diunggah mencakup 27 kabupaten/kota sepanjang 2020–2024 (135 baris). Delapan indikator utama telah dihitung ulang menjadi IDI, SEC, ESP dan J-NEST pada semua tahun dengan normalisasi global dan bobot CRITIC. Silakan buka Atlas atau Data & Audit untuk melihat skor tiap wilayah dan tahun. Kecocokan hasil dengan paper tidak menggantikan audit independen asal data BPS dan alur pengolahan GEE.\n\nSumber: tiga CSV pengguna dan Metodologi paper, hlm. 4–8.';
  if((q.includes('7 wilayah')||q.includes('anggota')||q.includes('kawasan rebana')||q.includes('perpres'))&&!q.includes('nilai'))return 'Tujuh anggota resmi Kawasan Rebana menurut Perpres 87/2021 adalah Kabupaten Subang, Sumedang, Indramayu, Majalengka, Cirebon, Kuningan, dan Kota Cirebon. Kabupaten Bekasi dan Karawang hanya digunakan sebagai pembanding Pantura dalam analisis perluasan.\n\nSumber: Cakupan spasial dan Tabel 3.';
  if((q.includes('bod')||q.includes('jalan tol')||q.includes('tol akses'))){return 'Kasus Tol Akses Patimban: RKL–RPL 2022 mencantumkan baku mutu BOD 3 mg/L; Laporan Pemantauan I memuat BOD 6–13,6 mg/L di tujuh titik berlabel baseline. Angka yang melampaui standar tidak otomatis membuktikan bahwa proyek jalan tol menyebabkannya. Penelitian belum memiliki rangkaian pengamatan sepadan beserta pemisahan sumber lain; dampak residual dan kompensasi belum dapat ditentukan.\n\nSumber: Tabel 9 dan pembahasan kasus, hlm. 21–23.';}
  if(q.includes('npv')||q.includes('air bersih')||q.includes('air patimban')||q.includes('pasokan air'))return 'Pada proyek air bersih Patimban, nilai investasi Rp134,2 miliar, IRR 10,9%, payback 11 tahun, dan skema BOT konsisten di dua profil publik. Namun, NPV ditulis “IDR 29.0 Milion” di lembar promosi dan “29,000,000,000” tanpa label mata uang pada bidang NPV portal. Penelitian meminta klarifikasi satuan dan model arus kas; tidak menetapkan nilai yang benar. Tambahan pasokan air juga belum dapat disimpulkan dari kapasitas terpasang saja.\n\nSumber: Tabel 10, hlm. 23–24.';
  if(q.includes('skk')||q.includes('siksa')||q.includes('sunda')||q.includes('tritangtu')||q.includes('karesian'))return 'SKK memberi tiga orientasi terarah: (1) pemeliharaan fungsi sumber penghidupan (Bagian I), (2) ketepatan orang/sumber pengetahuan (Bagian XV–XVI), dan (3) pembedaan peran serta tanggung jawab (tritangtu). Penerjemahan ke pemeriksaan investasi adalah usulan kontemporer penelitian. SKK tidak berisi ambang ekologis modern, izin investasi, atau rumus kompensasi.\n\nSumber: Tabel 6 dan pembahasan, hlm. 17–19.';
  if(q.includes('g0')||q.includes('g1')||q.includes('g2')||q.includes('g3')||q.includes('g4')||q.includes('penapisan')||q.includes('tahap'))return 'Alur J-NEST G0–G4 adalah: G0 kelengkapan bukti tentang fungsi, pengguna, kebutuhan proyek, dan data dasar; G1 batas hukum serta ekologis yang berlaku; G2 kesesuaian kebutuhan proyek dan alternatif desain; G3 kompetensi, kewenangan, tanggapan, dan tanggung jawab; G4 proyeksi atau bukti dampak residual sesuai tahap proyek. Ini pertanyaan untuk uji coba, bukan kriteria izin baru.\n\nSumber: Tabel 8, hlm. 20–21.';
  if(q.includes('kompensasi')||q.includes('residual')||q.includes('kerusakan'))return 'Skor J-NEST tidak bisa menghitung kewajiban maupun tarif kompensasi ekologis. Pada tahap perencanaan perlu menilai proyeksi dampak yang diperkirakan masih tersisa setelah mitigasi. Setelah pelaksanaan diperlukan pengamatan sepadan, atribusi perubahan dan bukti hasil mitigasi. Jika tidak cukup, status yang tepat adalah “belum dapat dinilai”, bukan “tidak ada dampak”.\n\nSumber: bagian G4 dan rekomendasi, hlm. 20–28.';
  if(q.includes('critic')||q.includes('bobot')||q.includes('normalisasi')||q.includes('rumus')||q.includes('agregasi'))return 'Indikator dinormalisasi minimum–maksimum pada gabungan 135 wilayah–tahun, dengan arah positif dan negatif sesuai konstruk. Bobot indikator di dalam masing-masing dimensi diperoleh menggunakan CRITIC. Tiga skor IDI, SEC, dan ESP diberi bobot sama (⅓) dalam indeks utama, dengan agregasi aritmetika. Agregasi geometrik digunakan sebagai uji sensitivitas, bukan indeks utama.\n\nSumber: Tabel 1 dan Persamaan (1)–(5), hlm. 5–6.';
  if(q.includes('korelasi')||q.includes('hubungan')||q.includes('industri')&&q.includes('vegetasi'))return 'Korelasi panel IDI–ESP sebesar −0,80924, sementara IDI–SEC sekitar 0,478 dan SEC–ESP sekitar −0,129. Hubungan negatif IDI–ESP tidak boleh ditafsirkan sebagai bukti bahwa satu proyek industri menyebabkan kerusakan ekologis. Sebagian proksi IDI dan ESP sama-sama menangkap keterbangunan/tutupan lahan; penelitian bersifat asosiasional.\n\nSumber: Struktur asosiasi, hlm. 12–13.';
  if(q.includes('sensitivitas')||q.includes('peringkat')||q.includes('geometri')||q.includes('spearman')||q.includes('ari'))return 'Agregasi aritmetika versus geometrik memiliki korelasi Spearman 0,797; pergeseran peringkat rata-rata 3,78 dan maksimum 11 posisi. Skenario SEC tanpa jumlah penduduk memberikan ARI klaster 0,377. Analisis ESP satu indikator (NDVI/LST) memerlukan verifikasi kode asal terkait bobot tunggal. Karena itu ranking tunggal tidak cukup untuk memutuskan lokasi investasi.\n\nSumber: Tabel 2 dan Tabel 4, hlm. 14–16.';
  if(q.includes('klaster')||q.includes('kmeans')||q.includes('tipologi'))return 'Penelitian menggunakan k-means pada tiga skor dimensi terstandardisasi tahun 2024 dan menetapkan 5 tipologi deskriptif: ESLI (6 wilayah), ETR (9), BHC (2), IET (6), dan ISC (4). Silhouette untuk k=5 adalah 0,416, sedikit di bawah k=6 sebesar 0,423. Keanggotaan tidak merupakan status izin atau batas daya dukung ekologis.\n\nSumber: Tabel 5, hlm. 16–17.';
  if(q.includes('siap investasi')||q.includes('skor tinggi')||q.includes('tertinggi')||q.includes('terbaik')||q.includes('izin'))return 'Tiga skor tertinggi tahun 2024 adalah Kabupaten Bandung (67,1), Kabupaten Bogor (65,8), dan Kabupaten Sukabumi (60,9). Namun, skor tinggi bukan bukti kesiapan proyek, legalitas lokasi, kualitas seluruh ekosistem, atau cadangan sumber daya. Kesesuaian proyek menuntut bukti tapak dan perbandingan alternatif.\n\nSumber: Gambar 4 dan pembahasan, hlm. 11–12.';
  if(mentions.length){const r=mentions.sort((a,b)=>b.name.length-a.name.length)[0];const d=dataFor(r,2024);return `${r.name} termasuk ${STUDY.types[r.typology].name} (${r.typology}), ${zoneText(r).toLowerCase()}. ${Number.isFinite(d.score)?`Skor J-NEST 2024: ${fmt(d.score)} / 100${Number.isFinite(d.rank)?`, peringkat ${d.rank}/27`:''}.`:'Skor rinci belum tersedia pada rekaman ini.'} ${['IDI','SEC','ESP'].every(k=>Number.isFinite(d[k]))?`Dimensi: IDI ${fmt(d.IDI)}, SEC ${fmt(d.SEC)}, ESP ${fmt(d.ESP)}.`:'Rincian tiga dimensi belum tersedia pada rekaman ini.'}\n\nTipologi/angka berasal dari ${d.source}. Profil ini tidak mengidentifikasi dampak atau izin proyek tertentu.`;}
  return 'Saya hanya dapat menjawab pertanyaan yang didukung oleh materi J-NEST–SKK pada aplikasi ini. Silakan bertanya mengenai tiga dimensi indeks, tujuh anggota Rebana, peringkat 2024, lima tipologi, sensitivitas, penapisan G0–G4, SKK, atau dua studi kasus Patimban. Untuk pertanyaan di luar cakupan itu, perlu menelaah sumber tambahan.';
}
function appendMessage(text,isUser=false){const host=$('chat-messages');const msg=document.createElement('div');msg.className='chat-msg'+(isUser?' user':'');if(!isUser){const av=document.createElement('div');av.className='chat-avatar-mini';av.textContent='J';msg.appendChild(av);}
  const bubble=document.createElement('div');bubble.className='chat-bubble';bubble.textContent=text;msg.appendChild(bubble);host.appendChild(msg);host.scrollTop=host.scrollHeight;return msg;}
function initChat(){
 appendMessage('Selamat datang! Tanya-J-NEST dapat menjelaskan metode dan hasil penelitian, termasuk skor wilayah 2020-2024. Jawaban AI adalah bantuan interpretasi; perhitungan indeks tetap berasal dari panel penelitian. Jangan memasukkan API key atau berkas rahasia dalam pertanyaan.');
 if(location.protocol==='file:')return;
 fetch('/api/status',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{
  if(!data)return;
  $('ai-mode-label').textContent=data.configured?'Kunci AI di server terpasang; siap diuji':'Mode lokal; OPENAI_API_KEY belum diatur';
  $('ai-mode-tag').textContent=data.configured?'API siap diuji':'Lokal';
 }).catch(()=>{});
}
async function askQuestion(question){
 const q=question.trim(); if(!q||state.aiBusy)return;
 appendMessage(q,true);$('chat-input').value=''; state.aiBusy=true; el('.send-button').disabled=true;
 const pending=appendMessage('Menelaah ringkasan paper dan panel J-NEST...'); let answer=null;
 try{
  if(location.protocol!=='file:'){
   const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),24500);
   try{
    const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q}),signal:controller.signal});
    if(res.ok){const data=await res.json();if(typeof data.answer==='string'&&data.answer.trim()){
     answer=data.answer;$('ai-mode-label').textContent='OpenAI API aktif · konteks paper dan panel terpilih';$('ai-mode-tag').textContent='AI aktif';
    }}
   }finally{clearTimeout(timer);}
  }
 }catch(_){/* Offline or API unavailable: use explicitly labelled deterministic local mode. */}
 pending.remove();
 if(!answer){$('ai-mode-label').textContent='Panduan lokal (tanpa AI generatif)';$('ai-mode-tag').textContent='Lokal';}
 appendMessage(answer||localAnswer(q));state.aiBusy=false;el('.send-button').disabled=false;$('chat-input').focus();
}

function downloadText(text,filename,mime='text/plain;charset=utf-8'){const blob=new Blob(['\ufeff',text],{type:mime});const href=URL.createObjectURL(blob);const link=document.createElement('a');link.href=href;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);}
function downloadJSON(object,filename){downloadText(JSON.stringify(object,null,2),filename,'application/json;charset=utf-8');}
function toCSV(rows){return rows.map(cols=>cols.map(value=>{const str=String(value??'');return /[",\r\n;]/.test(str)?`"${str.replace(/"/g,'""')}"`:str;}).join(',')).join('\r\n');}
function exportScores(){const rows=[['kode_bps','wilayah','tahun','JNEST','IDI','SEC','ESP','peringkat_tahunan_27','tipologi_referensi_2024','status_kawasan','sumber','PDRB_industri_ADHK2010_Rp_miliar','jumlah_penduduk_jiwa','kemiskinan_persen','TPT_persen','NDVI','NDBI','LST_derajat_C','cahaya_malam']];
 for(const yr of PANEL_MODEL.years)for(const r of REGIONS){const d=dataFor(r,yr),rec=PANEL_MODEL.row(r.id,yr);rows.push([rec?.bps_domain,r.name,yr,d.score,d.IDI,d.SEC,d.ESP,d.rank??'',r.typology,zoneText(r),d.source,rec?.manufacturing_grdp_adhk2010_billion_rupiah,rec?.population_total_persons,rec?.poverty_rate_percent,rec?.open_unemployment_rate_percent,rec?.ndvi_mean,rec?.ndbi_mean,rec?.lst_mean_c,rec?.nightlight_mean]);}
 downloadText(toCSV(rows),'J-NEST_hasil_reproduksi_panel_2020_2024.csv','text/csv;charset=utf-8');toast('135 skor dan delapan indikator panel olahan diunduh.');
}
function exportTemplate(){const rows=[['wilayah','tahun','JNEST','IDI','SEC','ESP'],...REGIONS.map(r=>[r.name,2023,'','','',''])];downloadText(toCSV(rows),'jnest-template-panel.csv','text/csv;charset=utf-8');}
function parseCSV(text){const delimiter=(text.split(/\r?\n/)[0].match(/;/g)||[]).length>(text.split(/\r?\n/)[0].match(/,/g)||[]).length?';':',';const rows=[];let row=[],val='',inQuote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(inQuote&&text[i+1]==='"'){val+='"';i++;}else{inQuote=!inQuote;}}else if(c===delimiter&&!inQuote){row.push(val);val='';}else if((c==='\n'||c==='\r')&&!inQuote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(val);if(row.some(x=>x.trim()))rows.push(row);row=[];val='';}else val+=c;}row.push(val);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function validateImportedCSV(text){const rows=parseCSV(text.replace(/^\ufeff/,''));if(rows.length<2)throw Error('CSV kosong atau hanya memiliki header.');const keys=rows.shift().map(x=>x.trim().toLowerCase());const ix=(s)=>keys.indexOf(s.toLowerCase());if(ix('wilayah')<0||ix('tahun')<0||ix('JNEST')<0)throw Error('Kolom wajib: wilayah, tahun, JNEST.');const result={};let ignored=0;for(const item of rows){const name=(item[ix('wilayah')]||'').trim();const matched=REGIONS.find(r=>r.name.toLocaleLowerCase('id-ID')===name.toLocaleLowerCase('id-ID'));const yr=Number(item[ix('tahun')]);if(!matched||!Number.isInteger(yr)||yr<2020||yr>2024){ignored++;continue;}const rec={};for(const k of ['JNEST','IDI','SEC','ESP']){const col=ix(k);const raw=col<0?'':(item[col]||'').trim();if(raw==='')rec[k==='JNEST'?'score':k]=null;else{const value=Number(raw.replace(',','.'));if(!Number.isFinite(value)||value<0||value>100){ignored++;rec.invalid=true;break;}rec[k==='JNEST'?'score':k]=value;}}if(rec.invalid)continue;const key=`${yr}:${matched.name}`;result[key]=rec;}if(!Object.keys(result).length)throw Error('Tidak ada baris sah. Gunakan nama wilayah persis seperti di template, tahun 2020–2024, dan skor 0–100.');return {data:result,valid:Object.keys(result).length,ignored};}
function refreshAfterImport(){const n=Object.keys(state.uploads).length;$('import-status').innerHTML=n?`<b>${n}</b> baris profil tambahan tersimpan di browser. Data impor ditandai berbeda dari nilai yang dikutip dari paper.`:'Belum ada data tambahan di browser ini.';renderOverview();renderAtlas();window.dispatchEvent(new Event('jnest:profiles-changed'));}
function openModal(){refreshAfterImport();$('data-modal').classList.remove('hidden');}
function closeModal(){$('data-modal').classList.add('hidden');}

function attachEvents(){
  els('.nav-item').forEach(e=>e.addEventListener('click',()=>{gotoPage(e.dataset.page);if(e.dataset.page==='policy')window.JNestPolicy?.navigate(Number(e.dataset.flowStep||0));}));
  document.addEventListener('jnest:policy-step',()=>{if(state.page==='policy')els('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page==='policy'&&Number(e.dataset.flowStep||0)===(window.JNestPolicy?.getStep?.()||0)));});
  $('mobile-menu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
  document.addEventListener('click',event=>{const link=event.target.closest('[data-goto]');if(link){gotoPage(link.dataset.goto);return;}const area=event.target.closest('[data-select-region]');if(area){selectRegion(area.dataset.selectRegion,true);return;}const gate=event.target.closest('[data-gate]');if(gate){state.gateIndex=Number(gate.dataset.gate);renderGateNav();renderGateDetail();return;}});
  document.addEventListener('keydown',event=>{const row=event.target.closest('[data-select-region]');if(row&&(event.key==='Enter'||event.key===' ')){event.preventDefault();selectRegion(row.dataset.selectRegion,true);}});
  $('overview-map-mode').addEventListener('click',event=>{const b=event.target.closest('[data-mode]');if(b){state.overviewMode=b.dataset.mode;renderOverview();}});
  $('atlas-region').addEventListener('change',event=>selectRegion(event.target.value));
  $('atlas-filter').addEventListener('change',event=>{state.atlasFilter=event.target.value;renderAtlas();});
  $('atlas-mode').addEventListener('change',event=>{state.atlasMode=event.target.value;renderAtlas();});
  $('atlas-year').addEventListener('change',event=>{state.atlasYear=Number(event.target.value);if(state.atlasYear!==2024&&state.atlasMode==='typology')state.atlasMode='score';renderAtlas();});
  $('compare-left').addEventListener('change',renderCompare);$('compare-right').addEventListener('change',renderCompare);
  $('download-scores').addEventListener('click',exportScores);
  $('weight-controls').addEventListener('input',event=>{if(event.target.matches('[data-weight]'))setWeight(event.target.dataset.weight,event.target.value);});
  $('reset-weights').addEventListener('click',()=>{state.weights={IDI:1/3,SEC:1/3,ESP:1/3};renderWeightControls();renderSimulation();toast('Bobot dikembalikan ke ⅓ per dimensi.');});
  $('aggregation-select').addEventListener('change',event=>{state.aggregation=event.target.value;renderSimulation();});
  $('screen-project').addEventListener('input',event=>{state.screening.project=event.target.value;saveScreen();});
  $('screen-stage').addEventListener('change',event=>{state.screening.stage=event.target.value;saveScreen();});
  $('screen-location').addEventListener('change',event=>{state.screening.location=Number(event.target.value);renderScreenContext();saveScreen();});
  $('gate-detail').addEventListener('change',event=>{if(event.target.matches('[data-check]')){state.screening.checks[event.target.dataset.check]=event.target.value;saveScreen();renderGateNav();updateProgress();}});
  $('gate-detail').addEventListener('input',event=>{if(event.target.id==='gate-notes'){state.screening.notes[STUDY.gates[state.gateIndex].id]=event.target.value;saveScreen();}});
  $('prev-gate').addEventListener('click',()=>{state.gateIndex=Math.max(0,state.gateIndex-1);renderGateNav();renderGateDetail();});
  $('next-gate').addEventListener('click',screenNext);
  $('reset-screen').addEventListener('click',()=>{if(!confirm('Hapus semua catatan penapisan di browser ini?'))return;state.screening={project:'',stage:'perencanaan',location:13,checks:{},notes:{}};state.gateIndex=0;saveScreen();renderScreen();toast('Catatan penapisan dikosongkan.');});
  $('export-screen').addEventListener('click',exportScreen);
  els('[data-case]').forEach(e=>e.addEventListener('click',()=>{state.case=e.dataset.case;renderCase();}));
  $('chat-form').addEventListener('submit',e=>{e.preventDefault();askQuestion($('chat-input').value);});
  els('[data-question]').forEach(e=>e.addEventListener('click',()=>askQuestion(e.dataset.question)));
  $('header-data-btn').addEventListener('click',openModal);$('close-modal').addEventListener('click',closeModal);
  $('data-modal').addEventListener('click',event=>{if(event.target===$('data-modal'))closeModal();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();});
  $('download-template').addEventListener('click',exportTemplate);
  $('clear-import').addEventListener('click',()=>{if(!Object.keys(state.uploads).length)return toast('Tidak ada data impor untuk dihapus.');if(!confirm('Hapus semua skor CSV yang pernah diimpor pada browser ini?'))return;state.uploads={};saveUploads();refreshAfterImport();toast('Data CSV tambahan telah dikosongkan.');});
  $('upload-csv').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw Error('CSV terlalu besar (maksimum 2 MB).');const text=await file.text();const parsed=validateImportedCSV(text);state.uploads={...state.uploads,...parsed.data};saveUploads();refreshAfterImport();$('import-status').textContent=`Berhasil membaca ${parsed.valid} baris; ${parsed.ignored} baris dilewati karena tidak cocok/tidak sah. Data disimpan hanya di browser.`;toast(`${parsed.valid} baris berhasil diimpor.`);}catch(err){$('import-status').textContent='Gagal: '+err.message;toast('Berkas CSV belum dapat dibaca.');}finally{event.target.value='';}});
}
function init(){fillIcons();fillSelect('atlas-region',REGIONS,state.selected);fillSelect('screen-location',REGIONS,state.screening.location);
  const comparables=REGIONS;fillSelect('compare-left',comparables,13);fillSelect('compare-right',comparables,11);
  $('compare-left').value='13';$('compare-right').value='11';
  renderOverview();renderRanking();renderAtlas();renderTypes();renderSensitivity();renderScreen();renderCase();renderSKK();renderMethod();initChat();attachEvents();
  const hash=decodeURIComponent(location.hash.slice(1));if($('page-'+hash))gotoPage(hash);else gotoPage('lab');
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
